import * as THREE from 'three';
import {recognizeKitchens} from './kitchen-layout.js?v=20261010-cooking68';
import {ROOM} from './housing-data.js?v=20261010-cooking68';
const ingredients={egg:{name:'卵',color:'#fff4bf'},cabbage:{name:'キャベツ',color:'#95cb69'},carrot:{name:'にんじん',color:'#e78c3e'},onion:{name:'玉ねぎ',color:'#efe4b7'}};
const recipes={egg:{name:'目玉焼き',needs:['egg']},vegetables:{name:'野菜炒め',needs:['cabbage','carrot','onion']}};
export function createCooking({scene,camera,get,send,notify,onStart,onEnd}){
  const style=document.createElement('style');style.textContent=`#cookingHUD[hidden],#cookingStart[hidden]{display:none!important}#cookingStart{position:fixed;left:50%;bottom:110px;transform:translateX(-50%);z-index:35;padding:12px 20px}#cookingHUD{position:fixed;inset:0;pointer-events:none;z-index:55;color:#eff8de;font-size:14px}#cookingHUD .cook-top,#cookingHUD .cook-tools,#cookingHUD .cook-choose{pointer-events:auto;background:#142d3cee;border:2px solid #658c96;padding:10px}#cookingHUD .cook-top{position:absolute;top:10px;left:10px;right:10px;display:flex;align-items:center;justify-content:space-between;gap:8px}#cookingHUD .cook-tools{position:absolute;right:10px;bottom:100px;width:min(330px,calc(100vw - 20px));max-height:42vh;overflow:auto}#cookingHUD button{font:inherit;color:#eff8de;background:#284c5a;border:1px solid #658c96;padding:10px;margin:3px}#cookingHUD button:disabled{opacity:.45}#cookingHUD .cook-choose{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(460px,90vw)}#cookingHUD .cook-choose[hidden]{display:none}#cookingHUD .cook-dot{position:absolute;top:50%;left:50%;color:#eff8de}#cookingHUD progress{width:100%}#cookingHUD p{margin:6px 0}#cookingHUD .cook-target{font-size:18px;font-weight:bold}@media(max-width:600px){#cookingHUD .cook-top{font-size:12px}#cookingHUD .cook-tools{width:235px;bottom:100px;font-size:12px}#cookingHUD button{padding:8px}}`;document.head.append(style);
  const start=document.createElement('button');start.id='cookingStart';start.hidden=true;start.textContent='クッキングを始める';document.body.append(start);
  const hud=document.createElement('section');hud.id='cookingHUD';hud.hidden=true;hud.innerHTML='<div class="cook-top"><span class="cook-state"></span><button data-act="end">調理を終了</button></div><span class="cook-dot">＋</span><div class="cook-choose"><h2>何を作りますか？</h2><p>冷蔵庫 → シンク → まな板 → コンロ → 盛り付け</p><button data-act="recipe-egg">目玉焼き</button><button data-act="recipe-vegetables">野菜炒め</button><p>カウンターから道具を取り出せます。WASD／スティックで移動し、道具の正面で操作してください。</p></div><div class="cook-tools"><p class="cook-target"></p><p class="cook-hand"></p><progress max="150" value="0"></progress><p class="cook-hint"></p><div class="cook-actions"></div></div>';document.body.append(hud);
  const visuals=new THREE.Group();visuals.name='Cooking workspace';scene.add(visuals);const held=new THREE.Group();if(!camera.parent)scene.add(camera);held.position.set(.28,-.38,-.85);camera.add(held);held.visible=false;
  const geo=new THREE.BoxGeometry(1,1,1),materials=new Map();function mat(color){if(!materials.has(color))materials.set(color,new THREE.MeshStandardMaterial({color,roughness:.8}));return materials.get(color);}
  function box(root,x,y,z,w,h,d,color){const mesh=new THREE.Mesh(geo,mat(color));mesh.position.set(x,y,z);mesh.scale.set(w,h,d);root.add(mesh);return mesh;}
  let zone=null,session=null,near=null,target=null,lastScan=-Infinity,lastUI=-Infinity,cache=new Map(),status='',models={};
  function worldPoint(station,lift=0){const h=zone.home;return new THREE.Vector3(h.x+station.x*h.front,ROOM.floor+station.y+station.def.h*.88+lift,h.z+station.z*h.front);}
  function equipment(role){return zone?.stations.find(s=>s.role===role);}
  function disposeRoot(root){root.clear();}
  function buildModels(){disposeRoot(visuals);models={};const counter=equipment('counter'),stove=equipment('stove'),sink=equipment('sink');models.board=new THREE.Group();models.board.position.copy(worldPoint(counter,.03));models.board.rotation.y=counter.yaw+(zone.home.front<0?Math.PI:0);visuals.add(models.board);box(models.board,0,0,0,.65,.04,.4,'#bd9166');box(models.board,.2,.05,.1,.24,.018,.04,'#aab7bc');box(models.board,.37,.05,.1,.1,.025,.045,'#354353');models.pan=new THREE.Group();models.pan.position.copy(worldPoint(stove,.04));models.pan.rotation.y=stove.yaw+(zone.home.front<0?Math.PI:0);visuals.add(models.pan);box(models.pan,0,0,0,.55,.05,.5,'#354353');for(const x of [-.27,.27])box(models.pan,x,.07,0,.035,.12,.5,'#657582');for(const z of [-.24,.24])box(models.pan,0,.07,z,.55,.12,.035,'#657582');box(models.pan,.48,.02,0,.4,.05,.09,'#263846');models.food=new THREE.Group();models.pan.add(models.food);models.fire=box(models.pan,0,-.055,0,.42,.025,.4,'#ee963b');models.pan.visible=false;models.water=box(visuals,0,0,0,.025,.38,.025,'#79cbd9');models.water.position.copy(worldPoint(sink,.03));models.water.position.y-=.12;models.water.visible=false;models.steam=new THREE.Group();models.pan.add(models.steam);for(let i=0;i<5;i++){const puff=box(models.steam,(i%3-1)*.14,.3+i*.14,0,.07,.09,.07,'#d7e2e0');puff.userData.phase=i;}models.steam.visible=false;}
  function heldModel(){held.clear();if(!session?.hand){held.visible=false;return;}held.visible=true;const h=session.hand;if(h.type==='pan'){box(held,0,0,0,.28,.045,.25,'#354353');box(held,.2,0,0,.2,.04,.05,'#263846');}else{const data=ingredients[h.id];if(h.cut)for(let i=0;i<4;i++)box(held,(i%2-.5)*.1,Math.floor(i/2)*.07,0,.07,.06,.07,data.color);else box(held,0,0,0,.16,.17,.14,data.color);}}
  function updateFood(){models.food.clear();for(const [i,id]of session.pan.ingredients.entries()){const color=session.heat>=150?'#57422d':ingredients[id].color;if(id==='egg'){box(models.food,0,.07,0,.38,.02,.34,'#fff4dc');box(models.food,0,.085,0,.13,.025,.13,color);}else for(let j=0;j<5;j++)box(models.food,(j%3-1)*.12,.075+i*.025,(Math.floor(j/3)-.5)*.14,.07,.04,.07,color);}}
  function begin(){if(!near)return;zone=near;session={recipe:null,hand:null,pan:{placed:false,oil:false,ingredients:[]},heat:0,fire:0,stirs:0,lastStir:0,elapsed:0,water:false,finished:false,startedAt:0};status='レシピを選んでください';near=null;start.hidden=true;hud.hidden=false;hud.querySelector('.cook-choose').hidden=false;hud.querySelector('.cook-choose p').textContent='冷蔵庫 → シンク → まな板 → コンロ → 盛り付け · 完成記録：目玉焼き '+(get().character.cookingStats?.egg||0)+'回／野菜炒め '+(get().character.cookingStats?.vegetables||0)+'回';buildModels();onStart(zone);drawUI();}
  function end(){if(!session)return;send({type:'cooking-stop'});session=null;zone=null;target=null;held.visible=false;held.clear();visuals.clear();hud.hidden=true;onEnd();}
  function action(id){if(id==='end'){end();return;}if(!session)return;
    if(id.startsWith('recipe-')){const recipe=id.slice(7);if(!recipes[recipe])return;session.recipe=recipe;hud.querySelector('.cook-choose').dataset.recipe=recipe;session.startedAt=performance.now();hud.querySelector('.cook-choose').hidden=true;send({type:'cooking-start',index:zone.index,kitchenId:zone.id,recipe});status='カウンターでフライパンを取るか、冷蔵庫で食材を取り出しましょう';drawUI();return;}
    if(!target||session.finished)return;
    if(id.startsWith('take-')&&target.role==='fridge'&&!session.hand){const ingredient=id.slice(5);if(!recipes[session.recipe].needs.includes(ingredient)||session.pan.ingredients.includes(ingredient))return;session.hand={type:'ingredient',id:ingredient,washed:ingredient==='egg',cut:false,cuts:0};status=ingredients[ingredient].name+'を取り出しました';}
    else if(id==='pan'&&target.role==='counter'&&!session.hand&&!session.pan.placed){session.hand={type:'pan'};status='フライパンをコンロへ運びましょう';}
    else if(id==='place-pan'&&target.role==='stove'&&session.hand?.type==='pan'){session.hand=null;session.pan.placed=true;models.pan.visible=true;status='油を入れて材料を用意しましょう';}
    else if(id==='water'&&target.role==='sink'){session.water=!session.water;models.water.visible=session.water;status=session.water?'蛇口を開けました':'蛇口を閉めました';}
    else if(id==='wash'&&target.role==='sink'&&session.water&&session.hand?.type==='ingredient'){session.hand.washed=true;status=ingredients[session.hand.id].name+'を洗いました';}
    else if(id==='prep'&&target.role==='counter'&&session.hand?.type==='ingredient'&&session.hand.washed){const h=session.hand;if(h.id==='egg'){h.cut=true;status='卵を割りました。フライパンへ入れましょう';}else{h.cuts++;h.cut=h.cuts>=3;status=h.cut?'切り終わりました。フライパンへ運びましょう':'包丁で切る '+h.cuts+'/3';}}
    else if(id==='oil'&&target.role==='stove'&&session.pan.placed){session.pan.oil=true;status='油を入れました';}
    else if(id==='add'&&target.role==='stove'&&session.pan.placed&&session.pan.oil&&session.hand?.cut){session.pan.ingredients.push(session.hand.id);session.hand=null;updateFood();status='材料をフライパンに入れました';}
    else if(id.startsWith('fire-')&&target.role==='stove'&&session.pan.placed){session.fire=Number(id.slice(5));status=['火を止めました','弱火','中火','強火'][session.fire];}
    else if(id==='stir'&&target.role==='stove'&&session.pan.ingredients.length){session.stirs++;session.lastStir=session.elapsed;status='ヘラでかき混ぜました';models.food.rotation.y+=.8;}
    else if(id==='plate'&&target.role==='counter'&&ready()){session.fire=0;session.water=false;session.finished=true;models.water.visible=false;session.quality=session.heat>=150?'焦げ気味':session.heat>=125?'しっかり焼き':'食べ頃';models.pan.visible=false;models.board.clear();box(models.board,0,.01,0,.7,.045,.55,'#f4eee2');models.food.removeFromParent();models.board.add(models.food);models.food.position.y=.01;send({type:'cooking-finish',index:zone.index,kitchenId:zone.id,recipe:session.recipe,quality:session.quality});status=recipes[session.recipe].name+'を盛り付けました · '+session.quality;}
    else if(id==='put-back'&&target.role==='fridge'){session.hand=null;status='冷蔵庫へ戻しました';}
    heldModel();drawUI();
  }
  function ready(){return recipes[session.recipe]?.needs.every(id=>session.pan.ingredients.includes(id))&&session.heat>=100&&(session.recipe==='egg'||session.stirs>=2);}
  function drawUI(){if(!session)return;hud.querySelector('.cook-state').textContent='クッキング · '+(recipes[session.recipe]?.name||'レシピ選択')+' · キッチン内だけ移動できます';hud.querySelector('.cook-target').textContent=session.finished?'料理完成':target?.def.name||'使う設備の正面へ移動';hud.querySelector('.cook-hand').textContent='手：'+(session.hand?.type==='pan'?'フライパン':session.hand?ingredients[session.hand.id].name+(session.hand.cut?'（下ごしらえ済み）':session.hand.washed?'（洗浄済み）':'（未洗浄）'):'何も持っていません');hud.querySelector('progress').value=session.heat;hud.querySelector('.cook-hint').textContent=status+' · '+(session.heat>=150?'焦げています。火を止めて盛り付けましょう':session.heat>=100?'食べ頃':session.heat>0?'加熱中':'未加熱');const buttons=[];const add=(id,label,enabled=true)=>buttons.push({id,label,enabled});
    if(session.finished)add('end','調理を終了');else if(session.recipe&&target){const role=target.role;if(role==='fridge'){for(const id of recipes[session.recipe].needs)add('take-'+id,ingredients[id].name+'を取る',!session.hand&&!session.pan.ingredients.includes(id));if(session.hand)add('put-back','食材を戻す');}if(role==='sink'){add('water',session.water?'水を止める':'水を出す');add('wash','食材を洗う',session.water&&session.hand?.type==='ingredient'&&!session.hand.washed);}if(role==='counter'){add('pan','フライパンを取る',!session.hand&&!session.pan.placed);add('prep',session.hand?.id==='egg'?'卵を割る':'まな板と包丁で切る',session.hand?.type==='ingredient'&&session.hand.washed&&!session.hand.cut);add('plate','お皿へ盛り付ける',ready()&&!session.hand);}if(role==='stove'){add('place-pan','フライパンを置く',session.hand?.type==='pan');add('oil','油を入れる',session.pan.placed&&!session.pan.oil);add('add','材料を入れる',session.pan.placed&&session.pan.oil&&!!session.hand?.cut);for(let i=0;i<4;i++)add('fire-'+i,['火を止める','弱火','中火','強火'][i],session.pan.placed);if(session.recipe==='vegetables')add('stir','ヘラでかき混ぜる',session.pan.ingredients.length>0);}}
    const list=hud.querySelector('.cook-actions'),buttonKey=JSON.stringify(buttons);if(list.dataset.buttons===buttonKey)return;list.dataset.buttons=buttonKey;list.replaceChildren();for(const entry of buttons){const button=document.createElement('button');button.dataset.act=entry.id;button.textContent=entry.label;button.disabled=!entry.enabled;list.append(button);}}
  hud.onclick=event=>{const button=event.target.closest('button[data-act]');if(button&&!button.disabled)action(button.dataset.act);};start.onclick=begin;
  function scan(){const s=get(),zones=[];for(const [index,room]of Object.entries(s.housing?.rooms||{})){if(!room.layout)continue;const key=index+':'+room.layout.rev;let result=cache.get(key);if(!result){result=recognizeKitchens(index,room.layout);cache.set(key,result);if(cache.size>100)cache.delete(cache.keys().next().value);}zones.push(...result.zones);}near=s.connected&&s.inStudio&&!s.paused&&!s.ragdoll&&!s.seated&&!s.sleeping&&!s.inBattle?zones.find(z=>z.allowed(s.player.position)&&Math.abs(s.player.position.y-ROOM.floor)<.8):null;start.hidden=!near;}
  function update(dt,now){const s=get();if(!session){if(now-lastScan>500){lastScan=now;scan();}return;}const room=s.housing?.rooms[zone.index];if(!s.connected||!s.inStudio||s.ragdoll||s.inBattle||!room||room.layout.rev!==zone.rev){notify('キッチンの状態が変わったため調理を終了しました');end();return;}if(!session.recipe)return;session.elapsed+=dt;if(session.pan.ingredients.length&&session.fire&&!session.finished){session.heat=Math.min(180,session.heat+dt*session.fire*(session.recipe==='vegetables'&&session.elapsed-session.lastStir>5?2.2:3.5));if(session.heat>=150&&!session.burned){session.burned=true;updateFood();}}models.fire.visible=session.fire>0;models.steam.visible=session.fire>0&&session.heat>30;for(const puff of models.steam.children){puff.position.y=.2+((session.elapsed*.25+puff.userData.phase*.16)%.9);puff.scale.setScalar(.06+(puff.position.y-.2)*.09);}if(now-lastUI<180)return;lastUI=now;target=null;let best=3.2;for(const station of zone.stations){const point=worldPoint(station),dx=point.x-s.player.position.x,dz=point.z-s.player.position.z,d=Math.hypot(dx,dz);if(d>best||(dx*Math.sin(s.yaw)+dz*Math.cos(s.yaw))/Math.max(.1,d)<.3)continue;const from=s.player.position.clone();from.y+=1.4;const to=point.clone();to.y-=.15;if(s.world.cameraPosition(from,to,.01,'furniture:'+zone.index+':'+station.item.id).distanceTo(to)>.1)continue;best=d;target=station;}drawUI();}
  return {get active(){return !!session;},get choosing(){return !!session&&!session.recipe;},get interaction(){return null;},update,end,constrain(position,previous){if(session&&!zone.allowed(position)){position.x=previous.x;position.z=previous.z;}},receive(message){if(message.playerId!==get().selfId)return;if(message.type==='cooking-result'){status=message.error||'料理の完成記録をサーバーに保存しました';if(session&&!session.finished&&message.error){notify(message.error);end();}else if(session)drawUI();return true;}return false;},key(event){if(!session)return false;if(event.code==='Escape'){event.preventDefault();end();return true;}return !session.recipe;}};
}
